INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(285,9,7,'Day 0','Pre-Assessment (2 hrs): baseline skill check (programming fundamentals + aptitude), used to validate track placement readiness.  ·  AI Tool Orientation (2 hrs): GitHub Copilot (personal productivity) setup/walkthrough + AWS Q Developer & enterprise GenAI tooling overview + prompt-engineering basics — the toolchain used throughout the programme.','{"Week":"Day 0","Total":"4*","Module":"Pre-Assessment + AI Tool Orientation","Prereq":"None — entry point","Date Range":"Before Wk 1","Hrs (L·H·A)":"2·2·0","Table of Content":"Pre-Assessment (2 hrs): baseline skill check (programming fundamentals + aptitude), used to validate track placement readiness.  ·  AI Tool Orientation (2 hrs): GitHub Copilot (personal productivity) setup/walkthrough + AWS Q Developer & enterprise GenAI tooling overview + prompt-engineering basics — the toolchain used throughout the programme.","Learning Outcomes":"Establish baseline readiness + shared AI toolchain familiarity","Hands-on Activities":"—","AI Integration Point":"AI Tool Orientation (GitHub Copilot — personal productivity; AWS Q Developer & LangChain/RAG tooling — capstone/infra overview)"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(286,9,10,'Wk 1–2','Java setup/IDE; variables & types; control flow; collections; exceptions; OOP (classes, encapsulation, inheritance, polymorphism)','{"Week":"Wk 1–2","Total":"80","Module":"Core Java & OOP","Prereq":"None — entry module","Date Range":"27 Jul – 07 Aug 26","Hrs (L·H·A)":"20·36·24","Table of Content":"Java setup/IDE; variables & types; control flow; collections; exceptions; OOP (classes, encapsulation, inheritance, polymorphism)","Learning Outcomes":"Set up Java dev environment; apply OOP fundamentals independently","Hands-on Activities":"Console calculator; menu-driven app; contact book; custom exception; domain classes; OOP refactors","AI Integration Point":"Copilot code completion in IDE setup; AI-generated OOP concept explanations (personal productivity)"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(287,9,14,'Wk 3','Components, props, state, events; hooks (useState/useEffect), Context API; routing; consuming REST APIs; build & deployment basics','{"Week":"Wk 3","Total":"40","Module":"React (Frontend) Essentials","Prereq":"None — parallel foundational skill","Date Range":"10 Aug – 14 Aug 26","Hrs (L·H·A)":"10·20·10","Table of Content":"Components, props, state, events; hooks (useState/useEffect), Context API; routing; consuming REST APIs; build & deployment basics","Learning Outcomes":"Build a responsive React frontend and consume a REST API — completing the full-stack loop with the Spring Boot service built later in the track","Hands-on Activities":"Build interactive UI components; hooks-based state management; React Router navigation; fetch/axios API consumption against a mock endpoint; production build","AI Integration Point":"Copilot component scaffolding; AI-assisted debugging (personal productivity)"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(288,9,18,'Wk 4','Python basics, syntax, data types; functions & modules; file I/O & JSON','{"Week":"Wk 4","Total":"32","Module":"Python Essentials","Prereq":"Wk 1–2 Core Java","Date Range":"17 Aug – 20 Aug 26","Hrs (L·H·A)":"10·12·10","Table of Content":"Python basics, syntax, data types; functions & modules; file I/O & JSON","Learning Outcomes":"Write maintainable, reusable Python scripts","Hands-on Activities":"CLI calculator/counter script; reusable module; config parser","AI Integration Point":"Copilot script scaffolding; AI-assisted debugging (personal productivity)"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(289,9,21,'Wk 5','SOLID principles; Singleton & Factory; layered architecture; dependency injection','{"Week":"Wk 5","Total":"32","Module":"Design Patterns & Architecture","Prereq":"Wk 4 Python + Wk 1–2 Core Java","Date Range":"21 Aug – 26 Aug 26","Hrs (L·H·A)":"10·12·10","Table of Content":"SOLID principles; Singleton & Factory; layered architecture; dependency injection","Learning Outcomes":"Structure code for clarity, testability, and separation of concerns","Hands-on Activities":"Refactor to SOLID; config manager + ProductFactory; 3-layer mini app; @Component/@Autowired refactor","AI Integration Point":"AI code review to spot SOLID violations; Copilot-assisted refactoring (personal productivity)"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(290,9,25,'Wk 6–7','Spring Boot intro; REST APIs; service/repo layers; validation/DTOs; exception handling; service discovery; Swagger; API security; secure coding','{"Week":"Wk 6–7","Total":"80","Module":"Spring Boot + Microservices","Prereq":"Wk 5 Design Patterns","Date Range":"27 Aug – 09 Sep 26","Hrs (L·H·A)":"26·32·22","Table of Content":"Spring Boot intro; REST APIs; service/repo layers; validation/DTOs; exception handling; service discovery; Swagger; API security; secure coding","Learning Outcomes":"Design, build, and secure production-grade microservices","Hands-on Activities":"Scaffold project; CRUD endpoints; layered services; global error handler; Eureka registration; JWT/OAuth2 security; API Gateway + Resilience4j","AI Integration Point":"Copilot REST boilerplate generation (personal productivity); RAG integration lab — LangChain-orchestrated retrieval feature, AWS Q Developer-assisted build"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(291,9,30,'Wk 8','JUnit 5; Mockito; integration tests; Jacoco; Git basics; PRs; Jenkins (freestyle + pipeline); env vars/credentials; SLF4J/Logback; Datadog/Grafana overview','{"Week":"Wk 8","Total":"56","Module":"Testing, Git & CI/CD","Prereq":"Wk 6–7 Spring Boot","Date Range":"10 Sep – 18 Sep 26","Hrs (L·H·A)":"20·24·12","Table of Content":"JUnit 5; Mockito; integration tests; Jacoco; Git basics; PRs; Jenkins (freestyle + pipeline); env vars/credentials; SLF4J/Logback; Datadog/Grafana overview","Learning Outcomes":"Test code reliably, automate builds, and monitor production issues","Hands-on Activities":"Unit + parameterized tests; mocked service tests; Jacoco report; PR workflow; freestyle + declarative Jenkins pipeline; secrets handling; structured logging","AI Integration Point":"AI-generated unit test stubs; Copilot test scaffolding; AI-assisted pipeline script generation (personal productivity)"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(292,9,34,'Wk 9–10','Docker (Dockerfile, volumes, networks); docker-compose; Kubernetes basics (pods, deployments, services); IAM, EC2, S3, VPC; ELB, Route 53; Lambda, CloudWatch, Auto Scaling','{"Week":"Wk 9–10","Total":"72","Module":"Containers & AWS","Prereq":"Wk 6–7 Spring Boot","Date Range":"21 Sep – 01 Oct 26","Hrs (L·H·A)":"24·28·20","Table of Content":"Docker (Dockerfile, volumes, networks); docker-compose; Kubernetes basics (pods, deployments, services); IAM, EC2, S3, VPC; ELB, Route 53; Lambda, CloudWatch, Auto Scaling","Learning Outcomes":"Containerize applications and deploy, secure, and cost-manage them on AWS","Hands-on Activities":"Dockerize Spring Boot app; docker-compose multi-service; Minikube deployment; launch EC2 + IAM role + VPC + S3; ELB + Route 53; cost estimate","AI Integration Point":"AWS Q Developer-assisted Dockerfile and Kubernetes manifest generation; Bedrock intro (optional lab); CloudWatch AI-alerting mention"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(293,9,39,'Wk 11','Threads & Executor; CompletableFuture async; Kafka architecture; producer/consumer apps; Snowflake architecture & queries; ETL concepts; Airflow DAGs','{"Week":"Wk 11","Total":"56","Module":"Concurrency, Kafka & Data Engineering","Prereq":"Wk 9–10 Containers & AWS","Date Range":"02 Oct – 12 Oct 26","Hrs (L·H·A)":"16·26·14","Table of Content":"Threads & Executor; CompletableFuture async; Kafka architecture; producer/consumer apps; Snowflake architecture & queries; ETL concepts; Airflow DAGs","Learning Outcomes":"Build concurrent, streaming applications and automate scheduled data pipelines","Hands-on Activities":"Thread-pool data loader; local Kafka topics; producer/consumer build; Snowflake table load/query; Python ETL; daily-scheduled DAG","AI Integration Point":"AI-generated async workflow patterns; Kafka + AI event-streaming mention; AI-assisted SQL generation; Copilot-assisted Airflow DAG authoring (personal productivity)"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(294,9,43,'Sprint','Dockerized Spring Boot microservice + React frontend: CRUD APIs, validation, Kafka events, CI/CD, AWS deployment, RAG-based GenAI feature','{"Week":"Sprint","Total":"40","Module":"Capstone","Prereq":"All Track A (Java FS) modules","Date Range":"13 Oct – 19 Oct 26","Hrs (L·H·A)":"0·26·14","Table of Content":"Dockerized Spring Boot microservice + React frontend: CRUD APIs, validation, Kafka events, CI/CD, AWS deployment, RAG-based GenAI feature","Learning Outcomes":"Design, build, and deploy a production-ready, full-stack, AI-augmented microservice","Hands-on Activities":"Build, containerize, automate, and deploy a production-ready, full-stack (Spring Boot + React) microservice with a RAG-integrated AI feature and a live demo","AI Integration Point":"RAG feature via LangChain/LangGraph, AWS Q Developer-assisted build, integrated with a SharePoint/Confluence knowledge base (required)"}');
