INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(355,12,21,'Day 18',replace('🤖 Microsoft Copilot\n& AI-Powered Productivity','\n',char(10)),'{"Day":"Day 18","Week":"Week 4 Advanced Cloud & Automation (40 Hours)","Course":"AB-900 Certification - Microsoft 365 Copilot and Agent Administration","Source":"PACKT","Remarks":"Include modules\nIntroduction to Microsoft 365, AI, and Copilot Foundations - 53m\nData Protection and Governance with Microsoft Purview and Copilot - 2hr 10m\nfrom given course","Duration":"03:03:00","Hands-On":"Use GitHub Copilot to enhance a case study code module; use Copilot in Excel to auto-generate analysis on case study data; draft case study documentation using Copilot in Word/Outlook; explore Copilot Studio to build a simple custom assistant","Subtopics":"MS Copilot Overview: What is Microsoft Copilot, Copilot across M365 ecosystem\n\nCopilot in M365 Apps: Word (drafting, summarising), Excel (data analysis, formulas), Outlook (email drafting, scheduling), Teams (meeting summaries, action items)\n\nGitHub Copilot: AI-assisted code completion, code review & explanation, test generation\n\nCopilot Studio: Building custom Copilots, plugins, and enterprise automation\n\nResponsible AI & Governance: Data privacy, AI ethics, enterprise adoption best practices","Proficiency":"Advanced","Published Date":"2026-04-29 00:00:00","Total Duration":"03:03:00","Learning Outcome":"Confidently use Microsoft Copilot across M365 and developer tools to boost productivity; understand enterprise Copilot adoption; apply AI-assisted workflows in real testing and development scenarios","Topic / Activity":"🤖 Microsoft Copilot\n& AI-Powered Productivity","Assessment & Engagement":"🏅 Badge: \"AI Productivity Champion\"\n⚡ Concept Checkpoint — MCQs","Customised Course names for Skill Assist Platform":"AB-900 Certification - Microsoft 365 Copilot and Agent Administration - Invesco_Testing"}');
