INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(357,12,23,'Day 20',replace('Serverless & Kubernetes on AWS\n+\n📦 Case Study Checkpoint 4','\n',char(10)),'{"Day":"Day 20","Week":"Week 4 Advanced Cloud & Automation (40 Hours)","Course":"Mastering Amazon EKS - Hands-On","Source":"PACKT","Duration":"04:33:00","Hands-On":"Deploy case study app container to EKS/Fargate; verify CI/CD triggers; run Power Automate flow end-to-end","Subtopics":"Deploying Containers, EKS, Fargate, Auto-Scaling, AI-assisted deployment troubleshooting\n\n📦 CS Checkpoint 4: Automation & Ops — CI/CD pipeline live, Power Automate/Apps workflow running, monitoring alerts configured, containers deployable on EKS/Fargate","Proficiency":"Basic","Published Date":"2025-09-26 00:00:00","Total Duration":"04:33:00","Learning Outcome":"Deliver a fully automated, observable deployment for the case study — Module 4 of capstone complete. All 4 modules now integrated.","Topic / Activity":"Serverless & Kubernetes on AWS\n+\n📦 Case Study Checkpoint 4","Assessment & Engagement":"🎯 Interactive Review Activity 5\n⚡ Concept Checkpoint — MCQs\n🏆 Milestone Assessment 4\n📦 CS Module 4 Merged — All Modules Ready"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(358,12,24,'Day 21','🔗 Sprint Day 1 — Integration & Polish','{"Day":"Day 21","Week":"🏁 Capstone Sprint (Integration & Demo)","Hands-On":"Fully integrated solution running end-to-end; architecture diagram finalised; README complete; demo rehearsed once with peer feedback","Subtopics":"All 4 modules now exist; today is about making them work as ONE cohesive solution\nActivities: end-to-end integration testing, bug fixes, UI/UX polish, documentation (README, architecture diagram), rehearsal of demo flow\nInstructor office hours — targeted help on blockers\nJira sprint board: move all stories to Done","Learning Outcome":"Synthesise all four weeks into a single working product; apply debugging, documentation, and integration skills under sprint conditions","Topic / Activity":"🔗 Sprint Day 1 — Integration & Polish","Assessment & Engagement":"⚡ Mid-sprint stand-up (15 min)\n🎯 Peer demo rehearsal — structured feedback form"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(359,12,25,'Day 22','🎤 Sprint Day 2 — Capstone Presentations','{"Day":"Day 22","Week":"🏁 Capstone Sprint (Integration & Demo)","Hands-On":"Each team presents to the panel; demo runs live without slides for the core flow; retrospective board completed in Jira","Subtopics":"Morning: Final preparation window (30 min)\nPresentation slots per team:\n  • Architecture walkthrough (tech stack, design decisions)\n  • Live demo of end-to-end solution\n  • Code walkthrough (key modules, CI/CD pipeline)\n  • Q&A from panel (instructors + peers)\nAfternoon: Sprint Retrospective in Jira — What went well? What to improve? Learnings logged","Learning Outcome":"Communicate technical work clearly to a mixed audience; reflect on the sprint process; receive structured evaluative feedback","Topic / Activity":"🎤 Sprint Day 2 — Capstone Presentations","Assessment & Engagement":"🥇 Best Project Award\n🎤 Retrospective presented to cohort"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(360,12,26,'Day 23','📝 Final Assessment & Certification','{"Day":"Day 23","Week":"🏁 Capstone Sprint (Integration & Demo)","Hands-On":"Complete individual assessment; receive personalised feedback report; update GitHub/LinkedIn with capstone project","Subtopics":"Individual written/scenario assessment covering all 4 weeks\nPersonalised feedback session — instructor 1:1 debrief on capstone performance\nCertification ceremony — badges, certificates, program completion\nCareer connect session: how to showcase this project on LinkedIn / GitHub portfolio","Learning Outcome":"Validate individual mastery across the full curriculum; walk away with a portfolio-ready project and a certified credential","Topic / Activity":"📝 Final Assessment & Certification","Assessment & Engagement":"🎓 Program Completion Certificate"}');
