INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(372,14,12,NULL,'Version Control Concepts + Repo Setup','{"Phase":"Phase 1 — Foundations","Topic":"Version Control Concepts + Repo Setup","Sub-Topic":"Why version control, repo structure, local vs remote, staging area & .gitignore, remote tracking branches","Phase / Module":"Git Essentials","Learning Format":"Self-paced Video + Embedded Assignments","Learning Outcome":"Learner understands version control fundamentals and can independently set up/commit to a repo","Artefact(s) Produced":"Repo with initial commit + cloned working copy (auto-captured)","Video / Content (hrs)":"1","Assignment / Hands-on (hrs)":"0.25","Assignment(s) — realistic time incl. buffer":"A1 (10 min): Initialize a local Git repository named ''loan-eligibility-service'', add the provided starter code skeleton, and make your first commit with a properly formatted commit message.\nA2 (10 min): Clone the shared ''loan-platform-common'' remote repository and verify your local working copy matches the remote HEAD."}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(373,14,13,NULL,'Branching & Merge Strategy + Conflict Resolution','{"Phase":"Phase 1 — Foundations","Topic":"Branching & Merge Strategy + Conflict Resolution","Sub-Topic":"Branching models, fast-forward vs 3-way merge, rebase vs merge trade-offs, PR review etiquette","Phase / Module":"Git Essentials","Learning Format":"Self-paced Video + Embedded Assignments","Learning Outcome":"Learner can choose the correct branch/merge strategy and resolve real merge conflicts independently","Artefact(s) Produced":"Final repo state (commit graph, auto-validated)","Video / Content (hrs)":"0.5","Assignment / Hands-on (hrs)":"0.5","Assignment(s) — realistic time incl. buffer":"A1 (15 min): Create feature branch ''feature/interest-rate-calc'', add a stub interest-rate-calculation method, and merge it back to main via a clean PR workflow.\nA2 (20 min): Resolve a seeded merge conflict between two parallel feature branches that both modify ''eligibility-rules.txt'', preserving both teams'' intended changes."}');
