INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(375,14,16,NULL,'RDBMS Concepts + Normalization Check','{"Phase":"Phase 1 — Foundations","Topic":"RDBMS Concepts + Normalization Check","Sub-Topic":"Tables, relationships, normalization (1NF–3NF), entity vs attribute vs relationship, functional dependency basics","Phase / Module":"Database Fundamentals","Learning Format":"Self-paced Video + Embedded Assignment","Learning Outcome":"Learner can explain normalization and justify schema design choices","Video / Content (hrs)":"1","Assignment / Hands-on (hrs)":"0.25","Assignment(s) — realistic time incl. buffer":"A1 (15 min): Identify and correct 2 normalization violations in a provided flawed Mphasis customer-loan schema (denormalize spotted, fix to 3NF)."}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(376,14,17,NULL,'ER Modeling & Constraints + Schema Design Lab','{"Phase":"Phase 1 — Foundations","Topic":"ER Modeling & Constraints + Schema Design Lab","Sub-Topic":"ER diagrams, primary/foreign keys, constraints, cardinality (1:1, 1:N, N:M), referential integrity","Phase / Module":"Database Fundamentals","Learning Format":"Self-paced Video + Embedded Assignments","Learning Outcome":"Learner can independently design a normalized relational schema and ER diagram","Artefact(s) Produced":"ER diagram (exported PNG/JSON)","Video / Content (hrs)":"1","Assignment / Hands-on (hrs)":"0.5","Assignment(s) — realistic time incl. buffer":"A1 (20 min): Design an ER diagram for the ''Customer'' and ''LoanApplication'' entities with correct PK/FK relationships.\nA2 (15 min): Extend the diagram to add ''CollateralDetails'' and ''ApprovalStatus'' entities with correct relationships to the existing entities."}');
