INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(491,21,3,NULL,'Python Refresher & Data Basics','{"Coverage":"Numpy, Pandas: Dataframe manipulation\nVisualization (matplotlib/seaborn)\nTypes of Data: Structured, semi-structured, Unstructured\nData Collection and Storage (application databases, user input files, organizational data stores)","Daily Topic":"Python Refresher & Data Basics","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(492,21,4,NULL,'Git & Cloud Basics','{"Coverage":"Git commands, commits, branching, Pull request\nCloud vs on-premise, Subscriptions, Resource groups concepts\nAzure Portal walkthrough of one subscription and its resources","Daily Topic":"Git & Cloud Basics","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(493,21,5,NULL,'AI Basics','{"Coverage":"Chronology of AI advancements (Machine learning → Deep learning → Computer Vision, NLP → LLMs)\nEvolution in Deep Learning Architectures: (RNNs to Transformers)\nDeep Learning Frameworks: Pytorch, Tensorflow and Keras Introduction\nEvaluation Metrics: Understanding of regression & classification metrics\nIntroduction to Claude (Anthropic); positioning vs GPT models; overview of Claude capabilities (reasoning, safety, long context); enterprise use cases for Claude","Daily Topic":"AI Basics","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(494,21,6,NULL,'Deployment Essentials','{"Coverage":"Dockerfile basics, building images, running containers, deploying containers to ACR.\nAzure Kubernetes Service - deploying and scaling AI apps on AKS\nAzure Pipelines - building workflows, testing, deploying code automatically\nSecurity & Compliance - Role-Based Access Control (RBAC), secrets management (Azure Key Vault).","Daily Topic":"Deployment Essentials","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(495,21,7,NULL,'MLOps','{"Coverage":"Model Lifecycle - Development, Release and Productionization\nMLFlow: Evaluation Metrics, Model Logging, Registering, Experimentation, Tracking, Monitoring","Daily Topic":"MLOps","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(496,21,8,NULL,'Introduction to Data Stores','{"Coverage":"Different types of data stores (SQL Databases, Document Stores)\nUnderstanding SQL Data Model (Normalization principle)","Daily Topic":"Introduction to Data Stores","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(497,21,9,NULL,'Structured Data','{"Coverage":"Introduction to SQL Syntax\nWriting SQL queries, functions, stored procedures, views, join strategies\nIntroduction to Azure SQL","Daily Topic":"Structured Data","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(498,21,10,NULL,'Unstructured/Semi-Structured Data - 1','{"Coverage":"Understanding of options for storing unstructured/semi-structured data: Azure Storage & Cosmos DB\nWhat is Azure Cosmos DB?\nKey Features (Global Distribution, Low Latency)\nUnderstanding Request Units (RUs)\nData Modelling with JSON Documents\nPartition Key Basics\nCRUD Operations in Cosmos DB","Daily Topic":"Unstructured/Semi-Structured Data - 1","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(499,21,11,NULL,'Unstructured/Semi-Structured Data - 2','{"Coverage":"Querying with SQL API\nConsistency Levels\nUsing Azure Portal for Cosmos DB\nBasic Security and Access Control\nIntroduction to OCR\nAzure Doc Intelligence\nReading pdfs through Open source libraries like PyMuPDF,Tesseract,PyPDF","Daily Topic":"Unstructured/Semi-Structured Data - 2","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(500,21,12,NULL,'Data Pipelines','{"Coverage":"Introduction to Data Pipelines\nUsing Python for Automation (Scripts, Scheduling)                                                                                                                                                                                                                                      - Introduction to pipeline creation tool: AzureML","Daily Topic":"Data Pipelines","Focus of the week":"Week 1: Foundations & Data Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(501,21,14,NULL,'Python Configs, Validation & Microservices Basics','{"Coverage":"Working with JSON, YAML, and Config files in Python\nIntroduction to Pydantic for Data Validation & Serialization\nLogging, Error Handling, and Structuring Python Projects\nREST API Principles & Microservices Overview\nFlask basics (webapp, routes) & Building Lightweight APIs","Daily Topic":"Python Configs, Validation & Microservices Basics","Focus of the week":"Week 2: Application Essentials & Generative AI Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(502,21,15,NULL,'Building Microservices with FastAPI,Flask & introduction to Azure','{"Coverage":"FastAPI Essentials: Path, Query, Body, Status Codes\nPydantic Schemas in FastAPI: Validation, Models, Nested Schemas\nUnit testing APIs with pytest\nAzure Fundamentals: Resource Groups, Storage, Managed Identity","Daily Topic":"Building Microservices with FastAPI,Flask & introduction to Azure","Focus of the week":"Week 2: Application Essentials & Generative AI Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(503,21,16,NULL,'Core Azure Services: Compute, Messaging, Load Balancing & Databricks','{"Coverage":"Azure Queue Services & Service Bus for Decoupling\nAzure Load Balancer & Application Gateway Basics\nApplication of Azure Functions & Azure App Services","Daily Topic":"Core Azure Services: Compute, Messaging, Load Balancing & Databricks","Focus of the week":"Week 2: Application Essentials & Generative AI Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(504,21,17,NULL,'Middleware, Queues & Distributed Architecture - 1','{"Coverage":"Middleware Patterns: Logging, Metrics, Retry, Circuit Breaker\nIntegrating Message Queues in Python (Azure Service Bus, RabbitMQ basics)\nLoad Balancing Strategies: Round Robin, Least Connections","Daily Topic":"Middleware, Queues & Distributed Architecture - 1","Focus of the week":"Week 2: Application Essentials & Generative AI Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(505,21,18,NULL,'Middleware, Queues & Distributed Architecture - 2','{"Coverage":"Using FastAPI/Flask with Uvicorn/Gunicorn for concurrency\nHealth Checks & Readiness Probes for Scalable APIs\nObservability: Structured Logging, Metrics (prometheus_client)","Daily Topic":"Middleware, Queues & Distributed Architecture - 2","Focus of the week":"Week 2: Application Essentials & Generative AI Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(506,21,19,NULL,'Introduction to Generative AI','{"Coverage":"What is Generative AI?\nTypes: Text, Image, Audio, Code generation\nKey models: GPT, DALL·E, Codex, Stable Diffusion (Diffusion, GANs, Transformers)\nApplications in enterprise AI (Use cases across industries)","Daily Topic":"Introduction to Generative AI","Focus of the week":"Week 2: Application Essentials & Generative AI Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(507,21,20,NULL,'LLM Fundamentals','{"Coverage":"Anatomy of LLMs (GPT, BERT, LLaMA)\nTransformer architecture basics\nPretraining vs. fine-tuning\nTokenization, embeddings\nClaude model family (Claude 3 – Opus, Sonnet, Haiku);\nComparison with GPT & open-source models; long context window capabilities","Daily Topic":"LLM Fundamentals","Focus of the week":"Week 2: Application Essentials & Generative AI Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(508,21,21,NULL,'Prompt Engineering & Model APIs','{"Coverage":"Prompt types: zero-shot, few-shot, chain-of-thought\nPrompt tuning\nPrompt design principles\nPrompt evaluation & debugging\nTools: LangChain, PromptLayer\nUsing OpenAI, Azure OpenAI, Anthropic APIs\nClaude-specific prompting techniques (structured prompts,\nConstitutional AI style prompting); differences vs GPT prompting; Claude API usage via direct API & LangChain","Daily Topic":"Prompt Engineering & Model APIs","Focus of the week":"Week 2: Application Essentials & Generative AI Essentials"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(509,21,23,NULL,'Retrieval-Augmented Generation (RAG) & Vector Databases','{"Coverage":"RAG architecture and flow\nVector DBs: Pinecone, Weaviate, FAISS, Azure AI Search\nIndexing, retrieval, and latency considerations\nUsing Claude in RAG pipelines; leveraging large context window vs retrieval; hybrid RAG + long-context approach","Daily Topic":"Retrieval-Augmented Generation (RAG) & Vector Databases","Focus of the week":"Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(510,21,24,NULL,'Gen AI Experimentation','{"Coverage":"Experimentation - Metrics Evaluation, Understanding Benchmarks, Understanding Model Capabilities\nTracking model performance\nLogging outcome and feedback loops.","Daily Topic":"Gen AI Experimentation","Focus of the week":"Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(511,21,25,NULL,'Gen AI Governance, Guardrails & Deployment Frameworks','{"Coverage":"Responsible AI principles (bias, hallucination, explainability)\nGuardrails: moderation, safety layers\nResponsible AI practices: EY principles\nFrameworks: LangChain, LlamaIndex, Haystack\nDeployment considerations: cost, latency, compliance","Daily Topic":"Gen AI Governance, Guardrails & Deployment Frameworks","Focus of the week":"Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(512,21,26,NULL,'Putting It All Together: Gen AI Use Case & Deployment','{"Coverage":"Gen AI API Example: Calling Azure OpenAI / HuggingFace APIs (simple RAG without vector DB)\nWrap-up: Best Practices, CI/CD Overview, Q&A & Next Steps\nClaude API integration alongside Azure OpenAI & HuggingFace; multi-model routing strategies","Daily Topic":"Putting It All Together: Gen AI Use Case & Deployment","Focus of the week":"Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(513,21,28,NULL,'Foundations of Agentic AI','{"Coverage":"What is Agentic AI? How it differs from traditional AI and GenAI?\nCore capabilities: Perceive, Reason, Act, Learn\nSingle-agent vs. Multi-agent systems\nReal-world applications: healthcare, mobility, customer service\nUsing Claude for reasoning-heavy tasks; multi-step decision-making capabilities in agents","Daily Topic":"Foundations of Agentic AI","Focus of the week":"Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(514,21,29,NULL,'Lifecycle & Frameworks','{"Coverage":"Agent lifecycle and planning loops\nFrameworks: LangChain, LangGraph\nIntegration of Claude with LangChain and LangGraph for agent workflows","Daily Topic":"Lifecycle & Frameworks","Focus of the week":"Week 3: Generative AI Essentials Continue and Generative AI and Agentic AI Systems"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(515,21,31,NULL,'Multi-Agent Architectures & Frameworks','{"Coverage":"Multi-agent coordination patterns (MCP)\nFrameworks: AI Foundry - Agent as a service and OpenAI Agents, CrewAI (overview of all and deep dive in to one)","Daily Topic":"Multi-Agent Architectures & Frameworks","Focus of the week":"Week 4: Generative AI and Agentic AI Systems Continued and Agentic AI System"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(516,21,32,NULL,'Tools, APIs & Middleware Integration','{"Coverage":"Memory, tool orchestration, and agent chaining\nConnecting agents to APIs, databases, and external tools\nMiddleware components: Redis, FastAPI, event queues\nClaude tool usage patterns; orchestration via APIs and middleware;\nComparison with function calling approaches","Daily Topic":"Tools, APIs & Middleware Integration","Focus of the week":"Week 4: Generative AI and Agentic AI Systems Continued and Agentic AI System"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(517,21,33,NULL,'Workflows','{"Coverage":"Agent orchestration with AutoGen Studio and Semantic Kernel [MCF]\nDesigning agent workflows and task delegation","Daily Topic":"Workflows","Focus of the week":"Week 4: Generative AI and Agentic AI Systems Continued and Agentic AI System"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(518,21,34,NULL,'Monitoring & Governance','{"Coverage":"Observability: tracing, logging, feedback loops\nGovernance: safety, guardrails, compliance\nLeveraging Claude safety layers in production; prompt-response auditing; compliance considerations","Daily Topic":"Monitoring & Governance","Focus of the week":"Week 4: Generative AI and Agentic AI Systems Continued and Agentic AI System"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(519,21,35,NULL,'Build an Agentic AI System','{"Coverage":"Building a multi-agent system (e.g., research + summarizer + notifier)\nDocument architecture, workflows, and governance strategy","Daily Topic":"Build an Agentic AI System","Focus of the week":"Week 4: Generative AI and Agentic AI Systems Continued and Agentic AI System"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(520,21,36,NULL,'Recap','{"Coverage":"Recap, Doubt Clearing, Focused Q&A Sessions","Daily Topic":"Recap","Focus of the week":"Week 4: Generative AI and Agentic AI Systems Continued and Agentic AI System"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(521,21,38,NULL,'Project Setup & Architecture','{"Coverage":"Define problem statement\nChoose project type (chatbot, summarizer, recommender)\nDraft architecture diagram\nSelect tech stack\nTeam formation and role assignment\nSetup GitHub repo, Azure Services and documentation structure","Daily Topic":"Project Setup & Architecture","Focus of the week":"Week 5: Capstone Project - A full stack Gen AI App"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(522,21,39,NULL,'Backend & AI Integration','{"Coverage":"Setup backend (FastAPI)\nIntegrate LLM APIs (OpenAI)\nSetup vector DB (FAISS/Pinecone)\nImplement embedding and retrieval logic\nTest API endpoints\nOptional use of Claude API alongside OpenAI; model selection strategy based on use case (cost, latency, reasoning)","Daily Topic":"Backend & AI Integration","Focus of the week":"Week 5: Capstone Project - A full stack Gen AI App"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(523,21,40,NULL,'Frontend & Middleware','{"Coverage":"Build UI (Streamlit)\nConnect frontend to backend\nAdd middleware (logging, error handling)\nImplement basic user interaction flow\nUI testing and feedback loop","Daily Topic":"Frontend & Middleware","Focus of the week":"Week 5: Capstone Project - A full stack Gen AI App"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(524,21,41,NULL,'Deployment & Testing','{"Coverage":"Containerize app with Docker\nDeploy to cloud (Azure)\nSetup CI/CD pipeline\nPerform unit, integration, and load testing\nFinalize documentation","Daily Topic":"Deployment & Testing","Focus of the week":"Week 5: Capstone Project - A full stack Gen AI App"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(525,21,42,NULL,'Wrap up for Demo & Documentation','{"Coverage":"Prepare documentation (problem, architecture, demo, runbook, learnings)\nConduct live demo in groups\nPeer review and feedback\nSubmit final GitHub repo","Daily Topic":"Wrap up for Demo & Documentation","Focus of the week":"Week 5: Capstone Project - A full stack Gen AI App"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(526,21,44,NULL,'Creating a Storyboard','{"Coverage":"Definition and purpose of storyboard\nExamples of storyboards and how storyboards enhance clarity and engagement\nElements of a good storyboard: Structure, Visual hierarchy and flow; Matching visuals to key messages\nStoryboarding tools: Canva\nAligning storyboard with audience needs","Daily Topic":"Creating a Storyboard","Focus of the week":"Week 6: Effective Presentations"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(527,21,45,NULL,'Art and Science of Storytelling','{"Coverage":"Introduction to storytelling in business\nStory structure: Setup, conflict, resolution; the role of emotion and memory\nIdentifying your core message and stakeholders\nUsing metaphors, analogies, and visuals\nTranslating storyboard into slides","Daily Topic":"Art and Science of Storytelling","Focus of the week":"Week 6: Effective Presentations"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(528,21,46,NULL,'Structure of a good presentation','{"Coverage":"Importance of structure in presentations: Common pitfalls\nIntroduction – Hook, Purpose, Agenda; Body – Key messages, supporting evidence; Conclusion – Summary, call to action\nUnderstanding your audience and adapting structure for different goals (inform, persuade, inspire)\nThe “What–So What–Now What” model with logical sequencing of ideas\nUsing transitions to maintain flow","Daily Topic":"Structure of a good presentation","Focus of the week":"Week 6: Effective Presentations"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(529,21,47,NULL,'Peer review and feedback','{"Coverage":"Why peer feedback matters\nGround rules for giving and receiving feedback\nThe SBI model (Situation–Behavior–Impact)\nDos and don’ts of peer critique\nRole of empathy and clarity","Daily Topic":"Peer review and feedback","Focus of the week":"Week 6: Effective Presentations"}');
