INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(1753,79,69,'Day 20','Spring Core','{"Day":"Day 20","Topic":"Spring Core","Sub Topics":"Introduction to Spring framework\nBenefits of Spring\nFeatures of Spring\nSpring Framework Architecture\nBean Factory\nApplication Context\nSpring Beans Scope\nDependency Injection/Inversion of Control\nSetter based DI\nConstructor based DI\nAutowiring of Beans - By Type\nAutowiring of Beans - By Name\nAutowiring of Beans - By Constructor\nAnnotations for Autowiring","Topic number":"15"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(1754,79,83,'Day 21','Spring MVC','{"Day":"Day 21","Topic":"Spring MVC","Sub Topics":"Introduction to ‘Spring MVC’ module\nFront Controller in Spring MVC\nComponents of Spring MVC\nDispatcher Servlet\nHandler Mapping bean\nView Resolver bean\nUnderstanding the flow of Spring MVC\nHandler Mapping\nController\nValidators\nMVC Form","Topic number":"16"}');
INSERT INTO "toc_rows" ("id","toc_file_id","row_number","day_label","topic","data") VALUES(1755,79,94,'Day 22','Object Relational Mapping','{"Day":"Day 22","Topic":"Object Relational Mapping","Sub Topics":"Define Persistence\nIdentify the problems with OR Mismatch\nDescribe alternatives for Object/Relational Mapping(ORM)\nExplain Hibernate as a preferred solution for ORM\nSmall demo on JDBC program for inserting a record\nProgram and verify a java application using hibernate framework","Topic number":"17","Duration in Hrs.":"16"}');
